/* Self-hosted lightweight EIP-1193 Provider & Contract Runtime for MediChain (Zero CDN Dependency) */
(function (global) {
  "use strict";

  // Minimal Keccak-256 implementation for Ethereum function selectors
  const KECCAK_ROUNDS = 24;
  const RC = [
    [0x00000000,0x00000001],[0x00000000,0x00008082],[0x80000000,0x0000808a],[0x80000000,0x80008000],
    [0x00000000,0x0000808b],[0x00000000,0x80000001],[0x80000000,0x80008081],[0x80000000,0x00008009],
    [0x00000000,0x0000008a],[0x00000000,0x00000088],[0x00000000,0x80008009],[0x00000000,0x8000000a],
    [0x00000000,0x8000808b],[0x80000000,0x0000008b],[0x80000000,0x00008089],[0x80000000,0x00008003],
    [0x80000000,0x00008002],[0x80000000,0x00000080],[0x00000000,0x0000800a],[0x80000000,0x8000000a],
    [0x80000000,0x80008081],[0x80000000,0x00008080],[0x00000000,0x80000001],[0x80000000,0x80008008]
  ];
  const R = [
    [0,36,3,41,18],[1,44,10,45,2],[62,6,43,15,61],[28,55,25,21,56],[27,20,39,8,14]
  ];
  function rotl64(hi, lo, n) {
    n %= 64;
    if (n === 0) return [hi, lo];
    if (n < 32) return [((hi << n) | (lo >>> (32 - n))) >>> 0, ((lo << n) | (hi >>> (32 - n))) >>> 0];
    n -= 32;
    return [((lo << n) | (hi >>> (32 - n))) >>> 0, ((hi << n) | (lo >>> (32 - n))) >>> 0];
  }
  function keccak256Hex(str) {
    const bytes = new TextEncoder().encode(str);
    const rate = 136;
    const totalLen = Math.ceil((bytes.length + 1) / rate) * rate;
    const padded = new Uint8Array(totalLen);
    padded.set(bytes);
    padded[bytes.length] = 0x01;
    padded[totalLen - 1] |= 0x80;

    const s = Array.from({ length: 25 }, () => [0, 0]);
    for (let offset = 0; offset < totalLen; offset += rate) {
      for (let i = 0; i < 17; i++) {
        const idx = offset + i * 8;
        const lo = (padded[idx] | (padded[idx+1]<<8) | (padded[idx+2]<<16) | (padded[idx+3]<<24)) >>> 0;
        const hi = (padded[idx+4] | (padded[idx+5]<<8) | (padded[idx+6]<<16) | (padded[idx+7]<<24)) >>> 0;
        s[i][0] ^= hi;
        s[i][1] ^= lo;
      }
      for (let round = 0; round < KECCAK_ROUNDS; round++) {
        const c = Array.from({ length: 5 }, (_, x) => [
          (s[x][0]^s[x+5][0]^s[x+10][0]^s[x+15][0]^s[x+20][0])>>>0,
          (s[x][1]^s[x+5][1]^s[x+10][1]^s[x+15][1]^s[x+20][1])>>>0
        ]);
        for (let x = 0; x < 5; x++) {
          const [dHi, dLo] = rotl64(c[(x+1)%5][0], c[(x+1)%5][1], 1);
          const tHi = (c[(x+4)%5][0] ^ dHi) >>> 0;
          const tLo = (c[(x+4)%5][1] ^ dLo) >>> 0;
          for (let y = 0; y < 5; y++) {
            s[x + 5*y][0] = (s[x + 5*y][0] ^ tHi) >>> 0;
            s[x + 5*y][1] = (s[x + 5*y][1] ^ tLo) >>> 0;
          }
        }
        const b = Array.from({ length: 25 }, () => [0, 0]);
        for (let x = 0; x < 5; x++) {
          for (let y = 0; y < 5; y++) {
            const [rHi, rLo] = rotl64(s[x + 5*y][0], s[x + 5*y][1], R[x][y]);
            b[y + 5*((2*x + 3*y)%5)] = [rHi, rLo];
          }
        }
        for (let x = 0; x < 5; x++) {
          for (let y = 0; y < 5; y++) {
            const i = x + 5*y, i1 = ((x+1)%5) + 5*y, i2 = ((x+2)%5) + 5*y;
            s[i][0] = (b[i][0] ^ ((~b[i1][0]) & b[i2][0])) >>> 0;
            s[i][1] = (b[i][1] ^ ((~b[i1][1]) & b[i2][1])) >>> 0;
          }
        }
        s[0][0] = (s[0][0] ^ RC[round][0]) >>> 0;
        s[0][1] = (s[0][1] ^ RC[round][1]) >>> 0;
      }
    }
    let out = "";
    for (let i = 0; i < 4; i++) {
      const [hi, lo] = s[i];
      for (const word of [lo, hi]) {
        for (let b = 0; b < 4; b++) out += ((word >>> (b * 8)) & 0xff).toString(16).padStart(2, "0");
      }
    }
    return "0x" + out;
  }

  function selectorOf(sig) {
    return keccak256Hex(sig).slice(0, 10);
  }

  function pad32Hex(hexNoPrefix) {
    return hexNoPrefix.padStart(64, "0");
  }

  function encodeUint256(val) {
    return pad32Hex(BigInt(val).toString(16));
  }

  function encodeAddress(addr) {
    const clean = String(addr).toLowerCase().replace(/^0x/, "");
    if (!/^[0-9a-f]{40}$/.test(clean)) throw new Error("Invalid Ethereum address: " + addr);
    return pad32Hex(clean);
  }

  function encodeString(str) {
    const bytes = new TextEncoder().encode(String(str));
    let hex = "";
    for (const b of bytes) hex += b.toString(16).padStart(2, "0");
    const paddedLen = Math.ceil(bytes.length / 32) * 64;
    return encodeUint256(bytes.length) + hex.padEnd(paddedLen, "0");
  }

  function decodeStringAt(hexData, byteOffset) {
    const charOffset = byteOffset * 2;
    const len = Number(BigInt("0x" + hexData.slice(charOffset, charOffset + 64)));
    const strHex = hexData.slice(charOffset + 64, charOffset + 64 + len * 2);
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = parseInt(strHex.slice(i * 2, i * 2 + 2), 16);
    return new TextDecoder().decode(bytes);
  }

  // Decode Record[] returned by getMyRecords()
  // struct Record { uint256 id; address patient; address doctor; string encryptedPayload; uint256 timestamp; bool active; }
  function decodeRecordArray(rawHex) {
    const hex = rawHex.replace(/^0x/, "");
    if (!hex || hex.length < 128) return [];
    const arrayOffset = Number(BigInt("0x" + hex.slice(0, 64))) * 2;
    const count = Number(BigInt("0x" + hex.slice(arrayOffset, arrayOffset + 64)));
    const headsStart = arrayOffset + 64;
    const records = [];
    for (let i = 0; i < count; i++) {
      const relTupleOffset = Number(BigInt("0x" + hex.slice(headsStart + i * 64, headsStart + (i + 1) * 64))) * 2;
      const tupleStart = headsStart + relTupleOffset;
      const id = BigInt("0x" + hex.slice(tupleStart, tupleStart + 64));
      const patient = "0x" + hex.slice(tupleStart + 64 + 24, tupleStart + 128);
      const doctor = "0x" + hex.slice(tupleStart + 128 + 24, tupleStart + 192);
      const payloadRelBytes = Number(BigInt("0x" + hex.slice(tupleStart + 192, tupleStart + 256)));
      const timestamp = BigInt("0x" + hex.slice(tupleStart + 256, tupleStart + 320));
      const active = BigInt("0x" + hex.slice(tupleStart + 320, tupleStart + 384)) !== 0n;
      const encryptedPayload = decodeStringAt(hex.slice(tupleStart), payloadRelBytes);
      records.push({ id, patient, doctor, encryptedPayload, timestamp, active });
    }
    return records;
  }

  class Signer {
    constructor(provider, address) {
      this.provider = provider;
      this.address = address;
    }
    async getAddress() {
      return this.address;
    }
  }

  class BrowserProvider {
    constructor(ethereum) {
      this.ethereum = ethereum;
    }
    async send(method, params = []) {
      return this.ethereum.request({ method, params });
    }
    async getSigner() {
      const accounts = await this.send("eth_accounts");
      if (!accounts || !accounts.length) {
        const req = await this.send("eth_requestAccounts");
        return new Signer(this, req[0]);
      }
      return new Signer(this, accounts[0]);
    }
  }

  class Contract {
    constructor(address, abi, signerOrProvider) {
      this.target = address;
      this.signer = signerOrProvider;
      this.provider = signerOrProvider.provider || signerOrProvider;

      this.getRole = async (userAddress) => {
        const data = selectorOf("getRole(address)") + encodeAddress(userAddress);
        const res = await this.provider.send("eth_call", [{ to: this.target, data }, "latest"]);
        return BigInt(res || "0x0");
      };

      this.registerUser = async (userAddress, userRole) => {
        const data = selectorOf("registerUser(address,uint8)") + encodeAddress(userAddress) + encodeUint256(userRole);
        return this._sendTx(data);
      };

      this.removeUser = async (userAddress) => {
        const data = selectorOf("removeUser(address)") + encodeAddress(userAddress);
        return this._sendTx(data);
      };

      this.createRecord = async (patient, encryptedPayload) => {
        const data = selectorOf("createRecord(address,string)")
          + encodeAddress(patient)
          + encodeUint256(64)
          + encodeString(encryptedPayload);
        return this._sendTx(data);
      };

      this.updateRecord = async (id, encryptedPayload) => {
        const data = selectorOf("updateRecord(uint256,string)")
          + encodeUint256(id)
          + encodeUint256(64)
          + encodeString(encryptedPayload);
        return this._sendTx(data);
      };

      this.deleteRecord = async (id) => {
        const data = selectorOf("deleteRecord(uint256)") + encodeUint256(id);
        return this._sendTx(data);
      };

      this.getMyRecords = async () => {
        const from = await this.signer.getAddress();
        const data = selectorOf("getMyRecords()");
        const res = await this.provider.send("eth_call", [{ from, to: this.target, data }, "latest"]);
        return decodeRecordArray(res);
      };
    }

    async _sendTx(data) {
      const from = await this.signer.getAddress();
      const txHash = await this.provider.send("eth_sendTransaction", [{
        from,
        to: this.target,
        data,
      }]);
      return {
        hash: txHash,
        wait: async () => {
          for (let i = 0; i < 120; i++) {
            const receipt = await this.provider.send("eth_getTransactionReceipt", [txHash]);
            if (receipt) {
              if (receipt.status === "0x0") throw new Error("Transaction reverted on-chain");
              return receipt;
            }
            await new Promise((r) => setTimeout(r, 400));
          }
          throw new Error("Transaction confirmation timed out");
        },
      };
    }
  }

  global.ethers = {
    BrowserProvider,
    Contract,
    isAddress: (addr) => /^0x[0-9a-fA-F]{40}$/.test(String(addr || "")),
  };
})(window);
